mapper.select:
${pagingTop} SELECT a.program_list_idx, b.reservation_idx, a.program_name, a.reservation_date, a.reservation_type, a.member_yn, a.use_time, a.homepage_id, b.member_id, b.member_name, b.member_phone, b.application_people, b.approve_yn, b.cancel_yn, b.reference, b.add_date FROM EXP_PROGRAM_LIST a, EXP_RESERVATION b WHERE a.program_list_idx = b.program_list_idx AND a.homepage_id = b.homepage_id AND b.homepage_id = #{homepage_id} AND b.member_id = #{member_id}
AND reservation_date = REPLACE(#{search_date}, '-', '')
ORDER BY a.reservation_date, a.use_time, b.add_date ${pagingBottom}

SELECT
	SUM(application_people) AS totalPeople
FROM
	EXP_RESERVATION
WHERE
	program_list_idx = #{program_list_idx}
AND	homepage_id = #{homepage_id}
AND	cancel_yn = 'N'

AND	reservation_idx != #{reservation_idx}

SELECT
	COUNT(*)
FROM
	EXP_RESERVATION
WHERE
	program_list_idx = #{program_list_idx}
AND	homepage_id = #{homepage_id}
AND	cancel_yn = 'N'

AND	reservation_idx != #{reservation_idx}

SELECT
	COUNT(*)
FROM
	EXP_RESERVATION
WHERE
	program_list_idx = #{program_list_idx}
AND	homepage_id = #{homepage_id}
AND	member_id = #{member_id}
